//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a temporary condition worth retrying.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry, with exponential growth capped at the maximum.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let max_delay = self.max_delay_ms;
        let base_delay = self.base_delay_ms.min(max_delay);
        let exponent = retry_number.saturating_sub(1);

        if exponent >= u64::BITS {
            return max_delay;
        }

        let multiplier = 1u64 << exponent;
        if base_delay > max_delay / multiplier {
            max_delay
        } else {
            base_delay * multiplier
        }
    }
}
#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_grows_exponentially_and_saturates() {
        let config = RetryConfig {
            max_attempts: 10,
            base_delay_ms: 25,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(1), 25);
        assert_eq!(config.delay_for_retry(2), 50);
        assert_eq!(config.delay_for_retry(3), 100);
        assert_eq!(config.delay_for_retry(4), 100);
    }

    #[test]
    fn huge_retry_number_does_not_overflow() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX / 2 + 1,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }

    #[test]
    fn base_delay_above_maximum_is_clamped() {
        let config = RetryConfig {
            max_attempts: 2,
            base_delay_ms: 500,
            max_delay_ms: 100,
        };

        assert_eq!(config.delay_for_retry(1), 100);
    }

    #[test]
    fn huge_retry_number_with_small_base_is_constant_time() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: 1,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => return Err(error),
            Err(error) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
                attempt += 1;
                drop(error);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });
        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });
        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call_and_caps_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });
        assert_eq!(
            result,
            Err(RetryError::Transient("still unavailable".into()))
        );
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn zero_max_attempts_still_makes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(0), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });
        assert!(result.is_err());
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_errors_with_bounded_backoff() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 7,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![7, 14, 20, 20]);
}

#[test]
fn public_api_returns_permanent_error_without_sleeping() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 7,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
